1	/** Actual private set serving observations; no ordinary runner/catalog/profile admission. */
2	import { execFileSync, type ChildProcess } from "node:child_process";
3	import { createHash, randomBytes } from "node:crypto";
4	import { mkdtempSync, readFileSync, realpathSync, rmSync } from "node:fs";
5	import { tmpdir } from "node:os";
6	import path from "node:path";
7	import { fileURLToPath } from "node:url";
8	import { expect, it } from "vitest";
9	import { Ajv2020 } from "ajv/dist/2020.js";
10	import type { ValidateFunction } from "ajv";
11	import { createRawHttpExchangeExecutor, HttpTransportError } from "@bdp/conformance";
12	import { assertSameServedProfileConfiguration } from "@bdp/conformance/testing";
13	import { isJsonSchemaUri, isJsonSchemaDateTime } from "@bdp/protocol";
14	import { installedTransactionBinding } from "../test-support/transactional-execution-binding.js";
15	const scope = "https://reference.invalid/acme/",
16	  bead = `${scope}types/bead`,
17	  owner = `${scope}types/owner`,
18	  link = `${scope}types/link`,
19	  owned = `${scope}types/owned`,
20	  schema = `${scope}schemas/n`;
21	const descriptors = [
22	  { id: bead, name: "Bead", describes: "bead", conformsTo: [], propertiesSchema: schema },
23	  {
24	    id: owner,
25	    name: "Owner",
26	    describes: "bead",
27	    conformsTo: [],
28	    propertiesSchema: schema,
29	    ownsOutgoing: { [owned]: { max: 32 } },
30	  },
31	  ...[link, owned].map((id) => ({
32	    id,
33	    name: id.endsWith("owned") ? "Owned" : "Link",
34	    describes: "link",
35	    conformsTo: [],
36	    propertiesSchema: schema,
37	    source: { conformsTo: [], external: "none" },
38	    target: { conformsTo: [], external: "none" },
39	  })),
40	];
41	const artifacts = {
42	  descriptors: descriptors.map((d) => ({ retrievalUri: d.id, utf8: JSON.stringify(d) })),
43	  schemas: [
44	    {
45	      retrievalUri: schema,
46	      utf8: JSON.stringify({
47	        $id: schema,
48	        type: "object",
49	        properties: { n: { type: "number" } },
50	        required: ["n"],
51	        additionalProperties: false,
52	      }),
53	    },
54	  ],
55	};
56	function object(value: unknown): Record<string, unknown> {
57	  if (!value || typeof value !== "object" || Array.isArray(value))
58	    throw Error("expected wire object");
59	  return value as Record<string, unknown>;
60	}
61	function array(value: unknown): Record<string, unknown>[] {
62	  if (!Array.isArray(value)) throw Error("expected wire array");
63	  return value.map(object);
64	}
65	it("installed valid sets preserve atomic effects, original receipts, owned versions and complete paged Events", async () => {
66	  type InstalledChild = {
67	    child: ChildProcess;
68	    ready: Record<string, unknown>;
69	    close(): Promise<void>;
70	  };
71	  type End = { code: number | null; signal: NodeJS.Signals | null };
72	  type Acquisition = {
73	    generation: number;
74	    acquisition: "unknown" | "acquired";
75	    refusal: "prelaunch-rejected" | "prelaunch-cleanup-unsettled" | null;
76	    phase: "initial" | "reopen";
77	    owned?: {
78	      handle: InstalledChild;
79	      pid: number | null;
80	      exit: End | null;
81	      closed: End | null;
82	      exitObserved: Promise<End | null>;
83	      closeObserved: Promise<End | null>;
84	      closing?: Promise<void>;
85	      closeSettled: boolean;
86	      closeSucceeded: boolean;
87	      closeFailed: boolean;
88	      closeFailure?: unknown;
89	    };
90	  };
91	  const started = performance.now(),
92	    controller = new AbortController(),
93	    deadline = setTimeout(
94	      () => controller.abort(new Error("installed set cohort deadline")),
95	      90000,
96	    ),
97	    failures: unknown[] = [],
98	    failureStages = new Set<string>(),
99	    observations: Record<string, unknown>[] = [],
100	    pending = new Set<Promise<unknown>>(),
101	    acquisitions: Acquisition[] = [],
102	    oracleOutcomes = ["O1", "O2", "O3", "O4", "O5"].map((id) => ({
103	      id,
104	      state: "unobserved" as "unobserved" | "pass" | "failed",
105	    })),
106	    receiptPages: [number | null, number | null] = [null, null],
107	    eventTraversals = {
108	      seed: { pages: [] as number[], count: null as number | null, complete: false },
109	      deletion: { pages: [] as number[], count: null as number | null, complete: false },
110	    },
111	    metadata = {
112	      mode: null as "workspace" | "external" | null,
113	      source: null as string | null,
114	      entry: null as string | null,
115	      entrySha256: null as string | null,
116	      fixtureSha256: null as string | null,
117	      workspaceDirty: null as boolean | "not-applicable-externally-bound" | null,
118	      diffSha256: null as string | null,
119	      disposition: null as "captured" | "not-applicable-externally-bound" | null,
120	      nullReason: "metadata-capture-failed" as string | null,
121	    };
122	  let directory: string | null = null,
123	    directoryDisposition: "removed" | "retained" | "unknown" = "unknown",
124	    child: InstalledChild | undefined,
125	    initialReady: Record<string, unknown> | null = null,
126	    reopenedReady: Record<string, unknown> | null = null,
127	    binding: ReturnType<typeof installedTransactionBinding> | null = null,
128	    receiptEntries: number | null = null,
129	    receiptComplete = false,
130	    groups: number | null = null,
131	    settled = 0,
132	    key = 0,
133	    phase = "metadata-capture-failed",
134	    ownershipUncertain = false,
135	    workEnded: number | null = null,
136	    cleanupStarted: number | null = null,
137	    cleanupEnded: number | null = null;
138	  const remember = (error: unknown) => {
139	    if (!failures.includes(error)) failures.push(error);
140	  };
141	  const problem = (stage: string) => {
142	    failureStages.add(stage);
143	    return new Error(stage);
144	  };
145	  const until = async <T>(promise: Promise<T>, end: number, stage: string): Promise<T> => {
146	    const remaining = end - performance.now();
147	    if (remaining <= 0) {
148	      void promise.catch(() => {});
149	      throw problem(stage);
150	    }
151	    let timer: ReturnType<typeof setTimeout> | undefined;
152	    try {
153	      return await Promise.race([
154	        promise,
155	        new Promise<never>((_, reject) => {
156	          timer = setTimeout(() => reject(problem(stage)), remaining);
157	        }),
158	      ]);
159	    } finally {
160	      clearTimeout(timer);
161	    }
162	  };
163	  const clean = (row: Acquisition) => {
164	    const owned = row.owned;
165	    return (
166	      row.acquisition === "acquired" &&
167	      owned !== undefined &&
168	      owned.exit?.code === 0 &&
169	      owned.exit.signal === null &&
170	      owned.closed?.code === 0 &&
171	      owned.closed.signal === null &&
172	      owned.closeSettled &&
173	      owned.closeSucceeded
174	    );
175	  };
176	  const requestClose = (row: Acquisition) => {
177	    const owned = row.owned;
178	    if (!owned) throw problem("child-close-unobserved");
179	    // One call per returned handle; the unchanged launcher also caches its Promise.
180	    return (owned.closing ??= Promise.resolve()
181	      .then(() => owned.handle.close())
182	      .then(
183	        () => {
184	          owned.closeSettled = true;
185	          owned.closeSucceeded = true;
186	        },
187	        (error: unknown) => {
188	          owned.closeSettled = true;
189	          owned.closeFailed = true;
190	          owned.closeFailure = error;
191	          throw error;
192	        },
193	      ));
194	  };
195	  const closeObserved = async (row: Acquisition, end: number) => {
196	    const owned = row.owned;
197	    if (!owned) throw problem("child-close-unobserved");
198	    try {
199	      await until(
200	        Promise.all([requestClose(row), owned.exitObserved, owned.closeObserved]),
201	        end,
202	        "cleanup-unsettled",
203	      );
204	      if (!owned.exit || owned.exit.code !== 0 || owned.exit.signal !== null)
205	        throw problem("child-exit-failed");
206	      if (!owned.closed || owned.closed.code !== 0 || owned.closed.signal !== null)
207	        throw problem("child-close-unobserved");
208	    } catch (error) {
209	      ownershipUncertain = true;
210	      throw error;
211	    }
212	  };
213	  const oracle = (index: number, check: () => void) => {
214	    const row = oracleOutcomes[index]!;
215	    try {
216	      check();
217	      row.state = "pass";
218	    } catch (error) {
219	      row.state = "failed";
220	      failureStages.add("clone-oracle-failed");
221	      throw error;
222	    }
223	  };
224	  try {
225	    // Owned throwing I/O and validator preparation must fail inside this callback.
226	    const root = fileURLToPath(new URL("../../../", import.meta.url));
227	    metadata.mode =
228	      process.env.BDP_TRANSACTIONAL_INSTALLED_ENTRY !== undefined ? "external" : "workspace";
229	    const git = (args: string[]) =>
230	      execFileSync("git", args, {
231	        cwd: root,
232	        encoding: "utf8",
233	        timeout: 2000,
234	        maxBuffer: 1048576,
235	      });
236	    if (metadata.mode === "external" && !process.env.BDP_TRANSACTIONAL_SOURCE_COMMIT)
237	      throw problem("metadata-capture-failed");
238	    const entry = realpathSync(
239	        process.env.BDP_TRANSACTIONAL_INSTALLED_ENTRY ??
240	          path.join(root, "packages/server/dist/transaction-installed-process.js"),
241	      ),
242	      source = process.env.BDP_TRANSACTIONAL_SOURCE_COMMIT ?? git(["rev-parse", "HEAD"]).trim(),
243	      fixture = {
244	        bytes: readFileSync(
245	          path.join(root, "packages/conformance/test-support/transactional/fixture-v1.json"),
246	        ),
247	      };
248	    if (!/^[a-f0-9]{40}$/.test(source)) throw problem("metadata-capture-failed");
249	    metadata.source = source;
250	    metadata.entry = entry;
251	    metadata.entrySha256 = createHash("sha256").update(readFileSync(entry)).digest("hex");
252	    metadata.fixtureSha256 = createHash("sha256").update(fixture.bytes).digest("hex");
253	    if (metadata.mode === "external") {
254	      metadata.workspaceDirty = "not-applicable-externally-bound";
255	      metadata.disposition = "not-applicable-externally-bound";
256	    } else {
257	      metadata.workspaceDirty = git(["status", "--porcelain"]).length > 0;
258	      metadata.diffSha256 = createHash("sha256")
259	        .update(git(["diff", "--binary", "HEAD"]))
260	        .digest("hex");
261	      metadata.disposition = "captured";
262	    }
263	    const { launchInstalledTransaction } = (await import(
264	      new URL("../../../scripts/transaction-installed-observation.mjs", import.meta.url).href
265	    )) as {
266	      launchInstalledTransaction(
267	        entry: string,
268	        configuration: unknown,
269	        signal: AbortSignal,
270	      ): Promise<InstalledChild>;
271	    };
272	    const ajv = new Ajv2020({ strict: true, allErrors: true });
273	    ajv.addFormat("uri", { type: "string", validate: isJsonSchemaUri });
274	    ajv.addFormat("date-time", { type: "string", validate: isJsonSchemaDateTime });
275	    const bundle = JSON.parse(readFileSync(path.join(root, "schemas/bdp-v0.schema.json"), "utf8"));
276	    ajv.addSchema(bundle);
277	    const validators: Record<string, ValidateFunction> = Object.fromEntries(
278	      ["mutationReceipt", "mutationReceiptPage", "eventPage", "changeGroup"].map((name) => [
279	        name,
280	        ajv.compile({ $ref: `${bundle.$id}#/$defs/${name}` }),
281	      ]),
282	    );
283	    const checked = (name: string, value: unknown) => {
284	      const validate = validators[name];
285	      if (!validate) throw Error("validator missing");
286	      expect(validate(value), JSON.stringify(validate.errors)).toBe(true);
287	    };
288	    metadata.nullReason = null;
289	    controller.signal.throwIfAborted();
290	    directory = mkdtempSync(path.join(tmpdir(), "bdp-set-installed-"));
291	    directoryDisposition = "retained";
292	    const token = randomBytes(32).toString("base64url"),
293	      configuration = {
294	        scope,
295	        directory,
296	        create: true,
297	        artifacts,
298	        credentials: [{ token, principal: "writer", canMutate: true }],
299	      };
300	    const launch = async (generation: number, input: typeof configuration) => {
301	      if (performance.now() >= started + 90000) throw problem("work-deadline");
302	      const row: Acquisition = {
303	        generation,
304	        acquisition: "unknown",
305	        refusal: null,
306	        phase: generation === 1 ? "initial" : "reopen",
307	      };
308	      acquisitions.push(row);
309	      try {
310	        const handle = await launchInstalledTransaction(entry, input, controller.signal);
311	        // No await/assertion between returned acquisition and event listener attachment.
312	        const owned: NonNullable<Acquisition["owned"]> = {
313	          handle,
314	          pid: handle.child.pid ?? null,
315	          exit: null,
316	          closed: null,
317	          exitObserved: Promise.resolve(null),
318	          closeObserved: Promise.resolve(null),
319	          closeSettled: false,
320	          closeSucceeded: false,
321	          closeFailed: false,
322	        };
323	        row.acquisition = "acquired";
324	        row.owned = owned;
325	        owned.exitObserved = new Promise((resolve) => {
326	          handle.child.once("exit", (code, signal) => {
327	            owned.exit = { code, signal };
328	            resolve(owned.exit);
329	          });
330	          // A pre-return lost exit event cannot be reconstructed from snapshots.
331	          if (handle.child.exitCode !== null || handle.child.signalCode !== null) resolve(null);
332	        });
333	        owned.closeObserved = new Promise((resolve) => {
334	          handle.child.once("close", (code, signal) => {
335	            owned.closed = { code, signal };
336	            resolve(owned.closed);
337	          });
338	        });
339	        if (owned.pid === null) throw problem("child-close-unobserved");
340	        return handle;
341	      } catch (error) {
342	        if (row.acquisition === "unknown") {
343	          ownershipUncertain = true;
344	          row.refusal =
345	            error instanceof AggregateError &&
346	            error.message === "installed transaction startup cleanup failed"
347	              ? "prelaunch-cleanup-unsettled"
348	              : "prelaunch-rejected";
349	          failureStages.add(row.refusal);
350	          if (generation === 2) failureStages.add("reopen-refused-pre-ready");
351	        }
352	        throw error;
353	      }
354	    };
355	    phase = "launch-failed";
356	    child = await launch(1, configuration);
357	    phase = "binding-validation-failed";
358	    initialReady = child.ready;
359	    binding = installedTransactionBinding(initialReady, source, fixture);
360	    const initialBinding = binding;
361	    expect(Object.keys(initialReady.targets as object)).toHaveLength(12);
362	    phase = "observation-failed";
363	    const send = async (
364	      target: string,
365	      body?: unknown,
366	      suppliedKey?: string,
367	      expectedStatus = 200,
368	    ) => {
369	      if (!child) throw Error("closed installed session");
370	      const current = installedTransactionBinding(child.ready, source, fixture);
371	      assertSameServedProfileConfiguration(initialBinding.served, current.served);
372	      expect(current.runtimeConfigurationIdentity).toBe(
373	        initialBinding.runtimeConfigurationIdentity,
374	      );
375	      const address = new URL(child.ready.listenUrl as string),
376	        url = new URL(target, scope).href,
377	        method = body === undefined ? ("GET" as const) : ("POST" as const);
378	      const execute = createRawHttpExchangeExecutor(
379	        { transport: "plain", host: address.hostname, port: Number(address.port) },
380	        {
381	          requestTimeoutMs: 5000,
382	          maximumBodyBytes: 1048576,
383	          exactMode: {
384	            scope,
385	            profile: "transactional",
386	            routes: [{ method, url }],
387	            maximumRequestHeaderBytes: 16384,
388	            maximumRequestBodyBytes: 65536,
389	            defaultCredentialRef: "writer",
390	            credentialHandles: [{ id: "writer", headerNames: ["authorization"] }],
391	            resolveCredentials: () => ({ authorization: `Bearer ${token}` }),
392	          },
393	        },
394	      );
395	      const requestBody = typeof body === "string" ? body : JSON.stringify(body);
396	      if (observations.length >= 32) throw problem("dispatch-cap-exceeded");
397	      const row: Record<string, unknown> = {
398	        ordinal: observations.length + 1,
399	        generation: acquisitions.at(-1)!.generation,
400	        method,
401	        url,
402	        requestBody,
403	        settled: false,
404	        received: false,
405	        validated: false,
406	        status: null,
407	        headers: null,
408	        body: null,
409	        wireResponseBase64: null,
410	        wireSha256: null,
411	        writeState: null,
412	        errorCategory: null,
413	      };
414	      observations.push(row);
415	      let task: ReturnType<typeof execute> | undefined;
416	      try {
417	        task = execute({
418	          method,
419	          url,
420	          signal: controller.signal,
421	          credentialRef: "writer",
422	          raw: {
423	            headerLines:
424	              body === undefined
425	                ? []
426	                : [
427	                    { name: "Content-Type", value: "application/json" },
428	                    { name: "Idempotency-Key", value: suppliedKey ?? `set_${key++}` },
429	                  ],
430	            ...(body === undefined ? {} : { bodyBytes: Buffer.from(requestBody!) }),
431	          },
432	        });
433	        pending.add(task);
434	        const response = await task;
435	        // Preserve all available response facts before any status/schema assertion.
436	        row.received = true;
437	        row.status = response.status;
438	        row.headers = response.headers;
439	        row.body = response.bodyText;
440	        row.writeState = response.exactRequest?.writeState ?? null;
441	        row.wireResponseBase64 =
442	          response.wireResponseBytes === undefined
443	            ? null
444	            : Buffer.from(response.wireResponseBytes).toString("base64");
445	        row.wireSha256 =
446	          response.wireResponseBytes === undefined
447	            ? null
448	            : createHash("sha256").update(response.wireResponseBytes).digest("hex");
449	        expect(response.status, response.bodyText).toBe(expectedStatus);
450	        expect(response.exactRequest?.writeState).toBe("complete");
451	        expect(response.wireResponseBytes?.length).toBeGreaterThan(0);
452	        if (expectedStatus === 200)
453	          for (const header of ["bdp-scope-epoch", "bdp-authorization-view", "bdp-scope-position"])
454	            expect(response.headers[header]?.length).toBeGreaterThan(0);
455	        const parsed = object(JSON.parse(response.bodyText));
456	        if (method === "POST" && expectedStatus === 200) checked("mutationReceipt", parsed);
457	        row.validated = true;
458	        return parsed;
459	      } catch (error) {
460	        if (row.received !== true) {
461	          row.errorCategory = error instanceof HttpTransportError ? error.category : "unavailable";
462	          row.writeState =
463	            error instanceof HttpTransportError ? (error.requestWriteState ?? null) : null;
464	          failureStages.add("exchange-rejected");
465	        } else failureStages.add("response-validation-failed");
466	        throw error;
467	      } finally {
468	        if (task) pending.delete(task);
469	        row.settled = true;
470	        settled++;
471	      }
472	    };
473	    const run = (operations: unknown[], suppliedKey?: string) =>
474	      send("operations/batch", { operations }, suppliedKey);
475	    const create = (id: string, type = bead) => ({
476	      operation: "createBead",
477	      id: `beads/${id}`,
478	      type,
479	      properties: { n: 0 },
480	      metadata: { stable: true },
481	    });
482	    await run([create("a"), create("b"), create("owner", owner)]);
483	    const linkIds = Array.from(
484	      { length: 32 },
485	      (_, i) => `${scope}links/l${String(i).padStart(2, "0")}`,
486	    );
487	    await run(
488	      linkIds.map((id) => ({
489	        operation: "createLink",
490	        id,
491	        type: link,
492	        source: "beads/a",
493	        target: "beads/b",
494	        properties: { n: 0 },
495	      })),
496	    );
497	    const collectEvents = async (target: string, kind: "seed" | "deletion") => {
498	      const captured = eventTraversals[kind];
499	      const events: Record<string, unknown>[] = [],
500	        lengths: number[] = [];
501	      let next: string | null = target;
502	      for (let pages = 0; next !== null; pages++) {
503	        if (pages >= 12) throw Error("bounded Event fixture page count exceeded");
504	        const page = await send(next);
505	        const rows = array(page.events);
506	        captured.pages.push(rows.length);
507	        checked("eventPage", page);
508	        lengths.push(rows.length);
509	        events.push(...rows);
510	        if (page.next !== null && typeof page.next !== "string") throw Error("invalid Event next");
511	        next = page.next;
512	      }
513	      captured.complete = true;
514	      captured.count = events.length;
515	      return { events, lengths };
516	    };
517	    const seededEvents = await collectEvents("events/", "seed"),
518	      lastSeedId = seededEvents.events.at(-1)?.id;
519	    expect(typeof lastSeedId).toBe("string");
520	    const feedStart = await send("changes/?start=now");
521	    expect(feedStart.groups).toEqual([]);
522	    const input = {
523	      collection: "links",
524	      selector: `$[?@.type == "${link}"]`,
525	      cardinality: { min: 32, max: 32 },
526	    };
527	    const receipt = await send("operations/delete-where", input, "delete32");
528	    receiptPages[0] = array(receipt.results).length;
529	    expect(receipt.status).toBe("completed");
530	    expect(array(receipt.results)).toHaveLength(32);
531	    expect(typeof receipt.next).toBe("string");
532	    const page = await send(receipt.next as string);
533	    receiptPages[1] = array(page.results).length;
534	    receiptComplete = page.next === null;
535	    if (receiptComplete) receiptEntries = receiptPages[0]! + receiptPages[1];
536	    checked("mutationReceiptPage", page);
537	    expect(array(page.results)).toHaveLength(1);
538	    expect(page.next).toBeNull();
539	    const allResults = [...array(receipt.results), ...array(page.results)];
540	    const assertResults = (rows: Record<string, unknown>[]) => {
541	      expect(rows[0]).toEqual({ operationIndex: 0, outcome: "matched", count: 32 });
542	      expect(
543	        rows.slice(1).map((r) => ({
544	          operationIndex: r.operationIndex,
545	          outcome: r.outcome,
546	          id: object(object(r.deleted).resource).id,
547	        })),
548	      ).toEqual(linkIds.map((id) => ({ operationIndex: 0, outcome: "deleted", id })));
549	    };
550	    assertResults(allResults);
551	    oracle(0, () => expect(() => assertResults(allResults.slice(0, -1))).toThrow());
552	    const suffixUrl = `events/?after=${encodeURIComponent(lastSeedId as string)}`;
553	    const suffix = await collectEvents(suffixUrl, "deletion");
554	    expect(suffix.lengths).toEqual([32, 32, 32]);
555	    const expectedFacts = linkIds.flatMap((id) => [
556	      { type: "deleted", subject: id },
557	      { type: "unlinked", subject: id },
558	      { type: "unlinked", subject: id },
559	    ]);
560	    const assertEvents = (events: Record<string, unknown>[]) =>
561	      expect(events.map((e) => ({ type: e.type, subject: e.subject }))).toEqual(expectedFacts);
562	    assertEvents(suffix.events);
563	    oracle(1, () => expect(() => assertEvents(suffix.events.slice(1))).toThrow());
564	    oracle(2, () =>
565	      expect(() =>
566	        assertEvents([
567	          ...suffix.events.slice(3, 6),
568	          ...suffix.events.slice(0, 3),
569	          ...suffix.events.slice(6),
570	        ]),
571	      ).toThrow(),
572	    );
573	    const feed = await send(`changes/?after=${encodeURIComponent(feedStart.after as string)}`);
574	    groups = array(feed.groups).length;
